#include <bits/stdc++.h>
using namespace std;
int main(){
    int n,m,a,b;
    cin>>n>>m>>a>>b;
    vector<int> dp(n+1, INT_MAX);
    dp[0]=0;
    for(int i=1;i<=n;i++){
        dp[i]=dp[i-1]+a;
        int prev = max(0, i-m);
        dp[i]=min(dp[i], dp[prev]+b);
    }
    cout<<dp[n]<<endl;
    return 0;
}
